import sys, json
import pandas as pd
import numpy as np

def to_float(x, nd=2):
    if pd.isna(x):
        return None
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- Totals ----
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True)
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(total_rev_tw), "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(total_rev_lw), "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(total_rev_ly), "formula": "sum(Revenue_LY)"
    })

    if total_rev_lw and not pd.isna(total_rev_lw) and total_rev_lw != 0:
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly and not pd.isna(total_rev_ly) and total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(total_units_tw), "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(total_units_lw), "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(total_orders_tw), "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(total_orders_lw), "formula": "sum(Orders_LW)"
    })

    # ---- Top 5 entities by Rank (this week's revenue) ----
    top5 = df.dropna(subset=['Rank']).sort_values('Rank').head(5)
    for _, row in top5.iterrows():
        if not pd.isna(row['Revenue_TW']):
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })
        if not pd.isna(row['Share_Pct']):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Share_Pct"
            })

    # ---- Top 3 WoW gainers ----
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    for _, row in wow_df.head(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 3 WoW losers ----
    for _, row in wow_df.tail(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
